INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES
('galla', 'Galla', 'demon', 'rifts', 0, 'Any evil or selfish', '{"IQ":"3D4+5","ME":"2D6+8","MA":"3D6","PS":"2D6+20","PP":"2D6+9","PE":"2D6+20","PB":"1D6","Spd":"1D6x10"}', NULL, NULL, '1D4x100+50', '1D4x10', NULL, 'P.S. is supernatural. In S.D.C. settings: 1D4x100 S.D.C., 2D6x10 hit points.', NULL, 12, '{"attacks":4,"initiative":1,"strike":3,"parry":3,"dodge":3,"roll":2,"pull":2}', 'Plus 2 to save vs magic and psionics, plus 4 to save vs horror factor; all in addition to attribute bonuses.', 'Select three W.P.s, plus land navigation 80%, wilderness survival 70%, track humans 65%, prowl 60%, climbing 70%/60% and swim 40%.', 'Nightvision 90 ft (27.4 m), infrared sight, sees the invisible and can itself go invisible whenever it likes. Regenerates 4D6 points a minute. Ordinary fire and heat do nothing; magical and mega-damage fire do half. Leaps 40 ft (12 m) up or across.', NULL, NULL, 'Seven feet tall (2.1 m)', '700 lbs (315 kg)', NULL, 'Native to an alien dimension. Can be found anywhere.', 'Made by Apsu as his army; most now serve Ereshkigal, and Tiamat keeps a share', NULL, NULL, 'A Sumerian demonic minion: a brawny, red-skinned warrior with a long golden or yellow beard and bright yellow eyes, a distant cousin of the baal-rog with the same fiery nature. Not the same thing as the Gallu Demon Bull, and ruled out as a player character.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.57'),
('hundred-handed', 'The Hundred-Handed', 'giant', 'rifts', 0, 'Any, but most (80%) are anarchist; rarely very good or very evil', '{"IQ":"1D4+3","ME":"3D4+6","MA":"4D6","PS":"2D6+60","PP":"3D6+6","PE":"5D6+10","PB":"1D6","Spd":"2D6"}', NULL, NULL, '3D6x10000', '1D6x50', NULL, 'P.S. is supernatural. No S.D.C.-world figures are printed. Average experience level 1D4+4. A rare spell or potion may shrink one to half size, halving combat abilities, attacks per melee and damage.', NULL, 18, '{"attacks":12,"initiative":2,"strike":3,"parry":6,"dodge":2}', 'Plus 6 to save vs horror factor; all in addition to attribute bonuses.', 'Few. Instinctive: swim 88%, climb 98%, rappel 88%. Speaks its own crude language plus Greek, Gobblely and Dragonese/Elf at 60%. Illiterate; learns no magic and usually no weapon beyond an uprooted tree or a giant robot swung as a club or thrown.', 'Nightvision 120 ft (36 m). Immune to disease, cold and heat; mega-damage and magical fire do half. Regrows a lost limb in 2D6 minutes and recovers 1D6x1000 M.D.C. every six hours.', NULL, NULL, '60 to 80 feet tall (18.3 to 24.4 m)', '100 to 160 tons', NULL, 'Tartarus, which Zeus has set them to guard', 'Zeus, the only one who was ever kind to them', 'The Titans they keep imprisoned', NULL, 'Eight-armed, not hundred-armed: colossal, hairless, pale giants with tiny bald heads and the minds of small children, whose raw strength let Zeus overthrow the Titans. The book ranks them as super-godlings, calls fighting one a lost cause next to tricking or persuading it, and advises against them as player characters outside an all-gods campaign.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.93'),
('furies', 'The Furies', 'monster', 'rifts', 0, 'Selfish or evil; usually evil', '{"IQ":"2D6+4","ME":"3D6","MA":"3D6","PS":"4D6+10","PP":"4D6","PE":"4D6","PB":"3D6","Spd":"4D6"}', NULL, NULL, '4D6x10', NULL, NULL, 'In S.D.C. settings: 4D6x10 S.D.C. and 2D6x10 hit points. No Horror Factor, P.P.E., number of attacks or attack damage is printed.', NULL, NULL, '{"initiative":3,"strike":4,"parry":5,"dodge":5}', 'Plus 6 to save vs horror factor; in addition to standard attribute bonuses.', 'Can only learn tracking, land navigation, wilderness survival and prowl. Knows two languages of choice at 98%.', 'Nightvision 200 ft (61 m). Regenerates 1D4x10 M.D.C. every five minutes; energy attacks do half damage. Hurts vampires the way a dragon does (Rifts Vampire Kingdoms), shrugs off vampire mind control and cannot be made a vampire, though one can kill her.', NULL, NULL, NULL, NULL, NULL, NULL, 'Jupiter and his lieutenants, the only ones able to command them', NULL, NULL, 'A mortal woman fused with a sliver of the Jupiter intelligence. He chooses women driven mad by abuse, promises revenge, then twists body and mind into a raging killer used as an assassin and shock trooper. From afar a Fury passes for a handsome woman in rags; up close the burning red eyes and howling give her away. A psychology roll at minus 40% and weeks of care with the Fury restrained might bring one back. Usually carries no equipment.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.100-101'),
('asurkan', 'Asurkan', 'demon', 'rifts', 0, 'Any evil or anarchist', '{"IQ":"2D4+4","ME":"3D4+4","MA":"3D4","PS":"3D6+10","PP":"3D4+10","PE":"3D4+10","PB":"1D4","Spd":"4D6+10"}', NULL, NULL, '4D6x10', '3D4x10', NULL, 'P.S. is supernatural. Spd is running; flying speed is double. In S.D.C. settings: 3D6x10 S.D.C. and 2D4x10 hit points. Experience level is printed as 11th level sorcerer.', NULL, 12, '{"attacks":4,"initiative":1,"strike":1,"dodge":2}', 'Plus 4 to save vs horror factor, plus 2 to save vs poison; in addition to attribute bonuses. Hand to Hand: Assassin. Four hand to hand attacks per melee round or two by magic. No attack damage is printed.', 'All wilderness and rogue skills at 52% (excluding computer hacking). Magically knows all languages.', 'Nightvision 200 ft (61 m), sees the invisible, goes invisible whenever it likes, flies, leaps 30 ft (9 m) up or 60 ft (18 m) across. Regenerates 3D6 M.D.C./S.D.C. a minute. Teleport self 54%, dimensional teleport 38%. Once an hour it can wrap itself in flame for about four minutes (16 melee rounds): immune to heat and fire, half damage from energy, and 30 extra M.D.C. (or S.D.C.).', 'Natural, not learned: chameleon, see aura, sense magic, sense evil, concealment, detect concealment, fear, fuel flames, fire bolt and blinding flash.', 'None', '4 feet (1.2 m)', '200 lbs (90 kg)', NULL, NULL, 'Kansa, whose minions they are; Ravana can summon 3D6 of them', NULL, NULL, 'Hindu lesser demons, the rank and file under Kansa: squat, fanged dwarves with outsized heads, claws and a bristle of spikes, cruel by nature and fond of human and D-bee flesh and blood. Kansa''s present giant body is one they built in their own image. Any weapon suits them, though they lean on their innate powers.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.138-139'),
('kravyads', 'Kravyads (The Devourers)', 'demon', 'rifts', 0, 'Any evil, usually miscreant', '{"IQ":"1D4+2","ME":"2D6+2","MA":"2D6","PS":"3D6+20","PP":"4D6","PE":"3D6+12","PB":"2D6","Spd":"2D6x10"}', NULL, NULL, '3D6x10', '1D4x10', NULL, 'P.S. is supernatural. In S.D.C. settings: 5D6+60 S.D.C., 1D6x10 hit points.', NULL, 14, '{"attacks":4,"initiative":2,"strike":4,"parry":4,"dodge":4,"roll":3}', 'Plus 3 to save vs horror factor, plus 3 to save vs magic and psionics; all in addition to attribute bonuses.', 'Prowl 50%, wilderness survival 80%, track humans 65%, climbing 75%/65%, and land navigation 45%.', 'Nightvision 200 ft (61 m), sees the invisible, goes invisible whenever it likes. Regenerates 3D6 M.D.C. a minute and regrows a severed limb in a day. Energy does half damage. Knows every language by magic.', 'None', 'None', '6 to 8 feet (1.8 to 2.4 m) tall', '400 to 800 lbs (180 to 360 kg)', NULL, 'Arrive on Earth through rifts in bands of 3D6', 'Usually controlled by a raksasha or another greater demon; steadier and obedient when led by a dybbuk, sowki or greater demon', NULL, NULL, 'Minor Hindu demons: furred, gorilla-like hulks with a boar''s head and two sharp black tusks, ravenous for human flesh. Left alone they rampage without thought, killing stock and anyone they meet. Near-animal wits make them easy to outmanoeuvre; they seldom touch technology and may bolt from energy weapons. Not meant as player characters.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.143-144'),
('evil-immortal', 'The Average Evil Immortal (Super Neuron Beast)', 'monster', 'rifts', 0, 'Most are miscreant or diabolic, with a few anarchists', '{"IQ":"30","ME":"23","MA":"22","PS":"20+3D6","PP":"16+2D6","PE":"20+2D6","PB":"4","Spd":"44"}', NULL, NULL, '2D4x100+400', '4D6x10+100', '1D4x100', 'M.D.C. is the main body; each arm has 200 M.D.C. and each tentacle 100. On S.D.C. worlds the main body is printed as 800 S.D.C. and hit points, each limb 100 S.D.C. and each tentacle 50. The attributes are printed as typical. Everything not printed here is as the typical neuron beast (Rifts Sourcebook One).', NULL, 14, '{"attacks":8}', '8 physical attacks per melee, or 3 psionic, or 2 by magic. No combat bonuses or attack damage are printed in this book.', NULL, 'Keen sight, sees the invisible, floats and hovers. Ordinary fire and heat do nothing and energy attacks do half. Regenerates 1D4x10 M.D.C. a minute, limbs included.', 'Level of experience 1D6+1; two spell attacks per melee. Spells: Globe of daylight, fingers of the wind, invisibility: simple, levitate, charismatic aura, multiple image, shadow meld, stone to flesh, calling, eyes of Thoth, tongues, magic pigeon, time slip, blinding flash, energy bolt, call lightning, domination, turn dead, exorcism, constrain being, and simple protection circle, plus 4D6 spells of choice from levels 1-7.', 'Master psionic, level 1D6+2; three attacks per melee. Powers: Total recall, telepathy, empathy, object read, see aura, see the invisible, sense evil, sense magic, bio-manipulation, empathic transmission, group mind block, mind block auto-defense, mentally possess others, mind bolt, mind bond, P.P.E. shield and psi-sword.', '20 feet (6 m)', '1400 lbs (630 kg)', NULL, 'India and Southeast Asia. Seven stay with Shiva the Annihilator at a ruined temple on a ley line nexus; the other ten work apart, each usually with 1D4 ordinary Neuron Beasts.', 'Shiva the Annihilator, their leader; ordinary Neuron Beasts', 'Vampires, which they hunt; they steer clear of true gods unless one looks weak enough to kill or capture', NULL, 'One of seventeen neuron beasts that Shiva the Annihilator recruited and that the hidden intelligence Devy''Orhal empowered. Four-armed and unearthly, they pass themselves off as returned Hindu gods, gather worshippers and have them raise pyramid-like temples on ley lines that damp and store the energy. They obey out of fear without understanding the plan, and never gather more than two at a time away from their leader.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.144');
