-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 6 creatures are in' AS assertion, count(*) AS got, 6 AS want
  FROM creatures WHERE slug IN ('galla', 'hundred-handed', 'furies', 'asurkan', 'kravyads', 'evil-immortal');
SELECT 'and 0 of them are playable' AS assertion, count(*) AS got, 0 AS want
  FROM creatures WHERE playable = 1 AND slug IN ('galla', 'hundred-handed', 'furies', 'asurkan', 'kravyads', 'evil-immortal');
SELECT 'the creatures carry 11 attacks' AS assertion, count(*) AS got, 11 AS want
  FROM stat_attacks WHERE owner_kind = 'creature' AND owner_slug IN ('galla', 'hundred-handed', 'furies', 'asurkan', 'kravyads', 'evil-immortal');

